def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    total_events = sum(len(events) for events in groups.values())
    if total_events == 0:
        return 0.0
    total_flags = sum(
        1
        for events in groups.values()
        for event in events
        if event["flagged"] is True
    )
    return total_flags / total_events


def flags_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (oldest first)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])
